"""C++ contract-profile link guards shared by projections and fixtures."""

from __future__ import annotations

from collections.abc import Iterable


def _c_string(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"')


def render_detect_mismatch_header(stamps: Iterable[tuple[str, object]]) -> str:
    """Render deterministic, field-addressable MSVC mismatch directives."""
    normalized = sorted((str(name), str(value).lower() if isinstance(value, bool) else str(value)) for name, value in stamps)
    lines = [
        "#pragma once",
        "// Generated by tools/build/sakura_build.py. Do not edit.",
        "#if defined(_MSC_VER)",
    ]
    lines.extend(
        f'#pragma detect_mismatch("{_c_string(name)}", "{_c_string(value)}")'
        for name, value in normalized
    )
    lines.extend(["#endif", ""])
    return "\n".join(lines)
